sys_trigger.script:
// ConfigSync Daily Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function() {
    try {
        var engine = new x_csync.ConfigSyncEngine();
        var instanceName = gs.getProperty('instance_name', '');
        var now = new GlideDateTime();
        var snapshotName = 'Daily Scan ' + now.getDate().getByFormat('yyyy-MM-dd');

        var snapId = engine.fingerprintInstance(instanceName, snapshotName, 'scheduled');
        if (!snapId) {
            gs.error('ConfigSync Daily Scan: fingerprintInstance returned empty sys_id');
            return;
        }

        // Compare against the previous snapshot
        var prevSnap = new GlideRecord('x_csync_snapshot');
        prevSnap.addQuery('sys_id', '!=', snapId);
        prevSnap.orderByDesc('sys_created_on');
        prevSnap.setLimit(1);
        prevSnap.query();

        if (prevSnap.next()) {
            var report = engine.compareSnapshots(prevSnap.getUniqueValue(), snapId);
            gs.info('ConfigSync Daily Scan: Drift Score=' + report.drift_score +
                    ', Gate=' + report.gate + ', Items=' + report.drift_count);
        } else {
            gs.info('ConfigSync Daily Scan: First snapshot created (no previous to compare). ID=' + snapId);
        }
    } catch (e) {
        gs.error('ConfigSync Daily Scan failed: ' + e.message);
    }
})();
